import * as T from './vendor/three.module.js';
// One short, infrequent streak in the same world-space sky as the stars.
export function createCafeMeteors(scene){
 const geometry=new T.BufferGeometry(),positions=new Float32Array(24),colors=new Float32Array(24);geometry.setAttribute('position',new T.BufferAttribute(positions,3));geometry.setAttribute('color',new T.BufferAttribute(colors,3));
 const material=new T.LineBasicMaterial({vertexColors:true,transparent:true,opacity:0,depthWrite:false,toneMapped:false,blending:T.AdditiveBlending}),line=new T.Line(geometry,material);line.name='Occasional island meteor';line.frustumCulled=false;line.visible=false;scene.add(line);
 let last=null,next=0,start=null,origin=new T.Vector3(),velocity=new T.Vector3();
 return {tick(seconds,night){if(!night){line.visible=false;start=null;next=seconds+20+Math.random()*35;last=seconds;return;}if(last===null||seconds<last||seconds-last>5){start=null;next=seconds+12+Math.random()*25;}last=seconds;if(start===null&&seconds>=next){start=seconds;const az=Math.random()*Math.PI*2,elevation=.45+Math.random()*.65;origin.set(Math.cos(az)*Math.cos(elevation),Math.sin(elevation),Math.sin(az)*Math.cos(elevation)).multiplyScalar(640);velocity.set(-Math.sin(az)*90,-65,Math.cos(az)*90);}if(start===null)return;const age=seconds-start;if(age>1.1){start=null;line.visible=false;next=seconds+35+Math.random()*55;return;}line.visible=true;material.opacity=Math.sin(age/1.1*Math.PI)*.85;for(let i=0;i<8;i++){const tail=i/7,p=origin.clone().addScaledVector(velocity,age-tail*.25);positions.set(p.toArray(),i*3);const glow=(1-tail)**2;colors.set([glow,glow*.93,glow*.80],i*3);}geometry.attributes.position.needsUpdate=true;geometry.attributes.color.needsUpdate=true;},state:()=>({active:line.visible,next})};
}
